// HE-TEXT: packs the Hebrew (src/game/text/he/<file>.js, the source you edit) into ONE module the game loads,
// src/game/he-text.js (the artifact holds at most 512 files; 51 Hebrew modules pushed it over). Run after editing any
// Hebrew file:  node tools/he-bundle.mjs        (tests/dialogue-check.mjs fails while he.js is out of date)
// text/he/i18n.js (i18n.js's own table, HE_I18N) is not packed: i18n.js imports it directly.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const TEXT = fileURLToPath(new URL('../src/game/text/', import.meta.url));
export function heBundle() {
  const parts = ['// GENERATED by tools/he-bundle.mjs from src/game/text/he/*.js: edit those files, then run the tool.',
    '// The Hebrew of every text file in one module (each English file imports it; it runs once).',
    "import { STR } from './i18n.js';", ''];
  for (const f of readdirSync(join(TEXT, 'he')).filter((n) => n.endsWith('.js') && n !== 'i18n.js').sort()) {
    const src = readFileSync(join(TEXT, 'he', f), 'utf8').replace(/^import \{ STR \} from '\.\.\/\.\.\/i18n\.js';\n/m, '');
    if (/^\s*(import|export)\b/m.test(src)) throw new Error(`he/${f}: only Object.assign(STR.he, …) blocks can be packed`);
    parts.push(`// ---- he/${f}`, src.trim(), '');
  }
  return parts.join('\n');
}
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(TEXT, '..', 'he-text.js'), heBundle());
  console.log('wrote src/game/he-text.js');
}
